/* LEGAD∞ vault v3. Reuses ojo-legado-v1 WebCrypto/IndexedDB foundations and
   Deivid Universal Inputs original-byte hashing, chunked base64 and CAS writes.
   No transport, model, professional-store access or native execution here. */
export const FORMAT='legad-encrypted-v3', ITERATIONS=600000, CHUNK=1024*1024, MAX_FILE=50*1024*1024, MAX_BACKUP=192*1024*1024;
const te=new TextEncoder(),td=new TextDecoder();
const assert=(v,m)=>{if(!v)throw new Error(m)};
export function b64(bytes){const a=new Uint8Array(bytes);let s='';for(let i=0;i<a.length;i+=32768)s+=String.fromCharCode(...a.subarray(i,i+32768));return btoa(s)}
export function un64(s,max=MAX_BACKUP){assert(typeof s==='string'&&s.length<=Math.ceil(max*4/3)+4&&/^[A-Za-z0-9+/]*={0,2}$/.test(s)&&s.length%4===0,'Codificación no válida');const t=atob(s);return Uint8Array.from(t,c=>c.charCodeAt(0))}
export async function sha256(bytes){return Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('')}
const random=n=>crypto.getRandomValues(new Uint8Array(n));
const uuid=()=>crypto.randomUUID();
const clone=x=>structuredClone(x);
async function aes(raw,usages=['encrypt','decrypt']){return crypto.subtle.importKey('raw',raw,{name:'AES-GCM'},false,usages)}
async function derive(pass,kdf){assert(typeof pass==='string'&&pass.length>=12&&pass.length<=1024,'Usa una frase de 12 a 1024 caracteres');const salt=un64(kdf.salt,32);assert(salt.length===16,'Sal no válida');assert(kdf.name==='PBKDF2'&&kdf.hash==='SHA-256'&&kdf.iterations===ITERATIONS,'Derivación no compatible');const key=await crypto.subtle.importKey('raw',te.encode(pass),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',hash:kdf.hash,iterations:kdf.iterations,salt},key,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}
async function seal(key,bytes,context){const iv=random(12);return {iv:b64(iv),cipher:b64(await crypto.subtle.encrypt({name:'AES-GCM',iv,additionalData:te.encode(context)},key,bytes))}}
async function open(key,record,context){assert(record&&typeof record==='object','Bloque ausente');const iv=un64(record.iv,12);assert(iv.length===12,'IV no válido');return new Uint8Array(await crypto.subtle.decrypt({name:'AES-GCM',iv,additionalData:te.encode(context)},key,un64(record.cipher)))}
const sealJSON=(key,x,c)=>seal(key,te.encode(JSON.stringify(x)),c);
async function openJSON(key,x,c){return JSON.parse(td.decode(await open(key,x,c)))}
function prefix(v){return FORMAT+':'+v.id}
export function validateEnvelope(v){
 assert(v&&v.format===FORMAT&&v.version===3&&typeof v.id==='string'&&/^[0-9a-f-]{36}$/.test(v.id),'Formato de cofre no reconocido');
 assert(v.cipher==='AES-256-GCM'&&v.kdf&&Number.isInteger(v.revision)&&v.revision>=0,'Cabecera no válida');
 assert(Array.isArray(v.records)&&v.records.length<=10000&&v.profile&&v.manifest&&v.keyWrap,'Cofre incompleto');
 assert(new Set(v.records.map(x=>x?.id)).size===v.records.length,'Identificadores duplicados');
 let size=0;for(const r of v.records){assert(typeof r.id==='string'&&/^[0-9a-f-]{36}$/.test(r.id)&&r.meta&&Array.isArray(r.media),'Recuerdo no válido');assert(r.media.length<=20,'Demasiados archivos');for(const m of r.media){assert(typeof m.id==='string'&&/^[0-9a-f-]{36}$/.test(m.id)&&Array.isArray(m.chunks)&&m.chunks.length<=50,'Archivo no válido');for(const c of m.chunks){assert(typeof c?.cipher==='string'&&c.cipher.length<=Math.ceil((CHUNK+16)*4/3)+4,'Fragmento no válido');size+=c.cipher.length;assert(size<=MAX_BACKUP,'Cofre demasiado grande')}}}
 return v;
}
async function refreshManifest(v,key){v.manifest=await sealJSON(key,{revision:v.revision,access:await sha256(te.encode(JSON.stringify({id:v.id,version:v.version,cipher:v.cipher,kdf:v.kdf,keyWrap:v.keyWrap,recoveryWrap:v.recoveryWrap,createdAt:v.createdAt}))),profile:await sha256(te.encode(JSON.stringify(v.profile))),records:await Promise.all(v.records.map(async r=>({id:r.id,sha256:await sha256(te.encode(JSON.stringify(r)))})))},prefix(v)+':manifest');return v}
async function verifyManifest(v,key){const m=await openJSON(key,v.manifest,prefix(v)+':manifest');assert(m.revision===v.revision&&m.access===await sha256(te.encode(JSON.stringify({id:v.id,version:v.version,cipher:v.cipher,kdf:v.kdf,keyWrap:v.keyWrap,recoveryWrap:v.recoveryWrap,createdAt:v.createdAt})))&&m.profile===await sha256(te.encode(JSON.stringify(v.profile)))&&Array.isArray(m.records)&&m.records.length===v.records.length,'Índice de integridad no válido');for(let i=0;i<v.records.length;i++)assert(m.records[i].id===v.records[i].id&&m.records[i].sha256===await sha256(te.encode(JSON.stringify(v.records[i]))),'El cofre se ha modificado o está incompleto')}
export async function createVault(pass,{name='Mon coffre personnel'}={}){
 const id=uuid(),raw=random(32),salt=random(16),recovery=random(32),v={format:FORMAT,version:3,id,cipher:'AES-256-GCM',kdf:{name:'PBKDF2',hash:'SHA-256',iterations:ITERATIONS,salt:b64(salt)},revision:0,records:[],createdAt:new Date().toISOString()};
 const key=await aes(raw),p=prefix(v);v.keyWrap=await seal(await derive(pass,v.kdf),raw,p+':key');v.recoveryWrap=await seal(await aes(recovery),raw,p+':recovery');v.profile=await sealJSON(key,{name:String(name).slice(0,100),createdAt:v.createdAt,beneficiaries:[],contributionsPrivate:true,ownerIntentRecorded:true},p+':profile');await refreshManifest(v,key);raw.fill(0);
 return {vault:v,key,recoveryCode:'LEGAD3-'+b64(recovery).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'')};
}
export async function unlockVault(v,secret,{recovery=false,full=true}={}){
 validateEnvelope(v);let raw;
 try{if(recovery){assert(typeof secret==='string'&&/^LEGAD3-[A-Za-z0-9_-]{43}$/.test(secret.trim()),'Clave de recuperación no válida');const s=secret.trim().slice(7).replace(/-/g,'+').replace(/_/g,'/')+'=';const r=un64(s,32);raw=await open(await aes(r),v.recoveryWrap,prefix(v)+':recovery');r.fill(0)}else raw=await open(await derive(secret,v.kdf),v.keyWrap,prefix(v)+':key')}catch(e){throw new Error(recovery?'No se pudo recuperar: clave o cofre incorrectos':'No se pudo abrir: frase incorrecta o cofre alterado')}
 const key=await aes(raw);raw.fill(0);await verifyManifest(v,key);const profile=await openJSON(key,v.profile,prefix(v)+':profile');const items=await readItems(v,key);if(full)for(const item of items)for(const m of item.attachments)await readMedia(v,key,item.id,m.id);
 return {vault:clone(v),key,profile,items};
}
export async function readItems(v,key){return Promise.all(v.records.map(async r=>{const i=await openJSON(key,r.meta,prefix(v)+':memory:'+r.id);assert(i.id===r.id&&typeof i.title==='string'&&typeof i.note==='string'&&Array.isArray(i.attachments),'Metadatos no válidos');assert(i.attachments.length===r.media.length&&new Set(i.attachments.map(x=>x.id)).size===i.attachments.length,'Índice de archivos no válido');for(const a of i.attachments){assert(r.media.some(m=>m.id===a.id)&&Number.isSafeInteger(a.size)&&a.size>0&&a.size<=MAX_FILE&&/^[a-f0-9]{64}$/.test(a.sha256)&&typeof a.name==='string'&&typeof a.type==='string','Metadatos de original no válidos')}return i}))}
export async function addMemory(v,key,data,files=[]){
 assert(files.length<=20,'Máximo 20 archivos por recuerdo');assert(String(data.title||'').trim().length>0,'Escribe un título');assert(String(data.note||'').length<=100000,'El texto es demasiado largo');
 const next=clone(v),id=uuid(),createdAt=new Date().toISOString(),attachments=[],media=[];
 for(const file of files){assert(file instanceof Blob&&file.size>0&&file.size<=MAX_FILE,'Cada original debe contener datos y ocupar como máximo 50 MB');const mid=uuid(),bytes=new Uint8Array(await file.arrayBuffer()),hash=await sha256(bytes),chunks=[];
  for(let start=0,index=0;start<bytes.length;start+=CHUNK,index++)chunks.push(await seal(key,bytes.subarray(start,start+CHUNK),prefix(v)+':media:'+id+':'+mid+':'+index));
  attachments.push({id:mid,name:String(file.name||'original').slice(0,500),type:String(file.type||'application/octet-stream').slice(0,200),size:file.size,lastModified:file.lastModified||null,sha256:hash,provenance:{producer:'user',channel:data.demo?'synthetic_demo':data.channel||'file_import',sourceTimestamp:createdAt,nativeAdmission:false,original:true}});media.push({id:mid,chunks});
 }
 const item={id,title:String(data.title).trim().slice(0,200),note:String(data.note||''),date:String(data.date||createdAt.slice(0,10)),createdAt,kind:attachments[0]?.type.split('/')[0]||'text',people:String(data.people||'').slice(0,1000),collection:String(data.collection||'Mes documents').slice(0,200),symbolicOpening:String(data.symbolicOpening||''),capsule:!!data.capsule,demo:!!data.demo,consent:{owner:!!data.ownerConsent,recordedPeople:!!data.peopleConsent,scope:'private_vault_only',recordedAt:createdAt,externallyVerified:false},derivatives:[],attachments,links:Array.isArray(data.links)?data.links.filter(x=>v.records.some(r=>r.id===x)).slice(0,50):[],authoring:'user_provided',visibility:'vault_holders_only'};
 assert(item.demo||(item.consent.owner&&(!item.people||item.consent.recordedPeople)),'Confirma los permisos para conservar este recuerdo');
 next.records.unshift({id,meta:await sealJSON(key,item,prefix(v)+':memory:'+id),media});next.revision++;await refreshManifest(next,key);validateEnvelope(next);return {vault:next,item};
}
export async function readMedia(v,key,itemId,mediaId){const r=v.records.find(x=>x.id===itemId);assert(r,'Recuerdo no encontrado');const item=await openJSON(key,r.meta,prefix(v)+':memory:'+r.id),meta=item.attachments.find(x=>x.id===mediaId),m=r.media.find(x=>x.id===mediaId);assert(meta&&m,'Original no encontrado');let total=0;const parts=[];for(let i=0;i<m.chunks.length;i++){const bytes=await open(key,m.chunks[i],prefix(v)+':media:'+itemId+':'+mediaId+':'+i);total+=bytes.length;assert(total<=MAX_FILE,'Original demasiado grande');parts.push(bytes)}const blob=new Blob(parts,{type:meta.type});assert(blob.size===meta.size&&await sha256(await blob.arrayBuffer())===meta.sha256,'La huella del original no coincide');return blob}
export async function deleteMemory(v,key,id){const next=clone(v);assert(next.records.some(r=>r.id===id),'Recuerdo no encontrado');next.records=next.records.filter(r=>r.id!==id);for(const r of next.records){const item=await openJSON(key,r.meta,prefix(v)+':memory:'+r.id);if(item.links.includes(id)){item.links=item.links.filter(x=>x!==id);r.meta=await sealJSON(key,item,prefix(v)+':memory:'+r.id)}}next.revision++;return refreshManifest(next,key)}
export async function updateMemory(v,key,id,changes){const next=clone(v),r=next.records.find(x=>x.id===id);assert(r,'Recuerdo no encontrado');const item=await openJSON(key,r.meta,prefix(v)+':memory:'+id);if(changes.derivative){const d=changes.derivative;assert(['transcription','translation','description'].includes(d.kind),'Tipo derivado no válido');item.derivatives.push({id:uuid(),kind:d.kind,text:String(d.text||'').slice(0,100000),language:String(d.language||'es').slice(0,10),producer:'user',assisted:false,reviewed:true,createdAt:new Date().toISOString(),sourceIds:item.attachments.map(m=>m.id)})}if(changes.links)item.links=changes.links.filter(x=>x!==id&&next.records.some(m=>m.id===x)).slice(0,50);r.meta=await sealJSON(key,item,prefix(v)+':memory:'+id);next.revision++;await refreshManifest(next,key);return next}
export async function changePassword(v,key,currentPass,newPass,{recovery=false}={}){await unlockVault(v,currentPass,{recovery,full:false});const next=clone(v),salt=random(16);next.kdf={name:'PBKDF2',hash:'SHA-256',iterations:ITERATIONS,salt:b64(salt)};let raw;if(recovery){const s=currentPass.trim().slice(7).replace(/-/g,'+').replace(/_/g,'/')+'=';raw=await open(await aes(un64(s,32)),v.recoveryWrap,prefix(v)+':recovery')}else raw=await open(await derive(currentPass,v.kdf),v.keyWrap,prefix(v)+':key');next.keyWrap=await seal(await derive(newPass,next.kdf),raw,prefix(v)+':key');raw.fill(0);next.revision++;await refreshManifest(next,key);return next}
export async function exportVault(v){validateEnvelope(v);const data=clone(v);assert(JSON.stringify(data).length<MAX_BACKUP-1024,'Le cofre supera el límite de exportación de esta versión');const checksum=await sha256(te.encode(JSON.stringify(data)));return JSON.stringify({format:'legad-backup-v3',exportedAt:new Date().toISOString(),checksumAlgorithm:'SHA-256',checksum,vault:data})}
export async function parseBackup(text){assert(typeof text==='string'&&text.length<=MAX_BACKUP,'Copia demasiado grande');const o=JSON.parse(text);assert(o.format==='legad-backup-v3'&&o.checksumAlgorithm==='SHA-256','Formato de copia no reconocido');assert(o.checksum===await sha256(te.encode(JSON.stringify(o.vault))),'Copia incompleta o alterada');return validateEnvelope(o.vault)}
// Legacy format is migrated only after ALL legacy records and originals validate.
export async function migrateLegacy(text,oldPass,newPass){const old=JSON.parse(text);assert(old.format==='ojo-legado-encrypted-v1'&&Array.isArray(old.items)&&old.items.length<=10000,'No es una copia del prototipo');const salt=un64(old.salt,16),raw=await crypto.subtle.importKey('raw',te.encode(oldPass),'PBKDF2',false,['deriveKey']);assert(salt.length===16,'Sal no válida');const k=await crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:310000,hash:'SHA-256'},raw,{name:'AES-GCM',length:256},false,['decrypt']);async function dec(x){return JSON.parse(td.decode(await crypto.subtle.decrypt({name:'AES-GCM',iv:un64(x.iv,12)},k,un64(x.cipher))))}assert((await dec(old.check)).ok,'Frase incorrecta');const decoded=[];for(const r of old.items){const o=await dec(r);assert(typeof o.title==='string'&&typeof o.note==='string','Recuerdo antiguo no válido');let files=[];if(o.attachment){const a=o.attachment;assert(typeof a.data==='string'&&a.data.startsWith('data:')&&a.data.includes(';base64,'),'Original antiguo no compatible');const b=un64(a.data.slice(a.data.indexOf(',')+1),MAX_FILE);files=[new File([b],a.name||'original',{type:a.type||'application/octet-stream'})]}decoded.push({o,files})}const fresh=await createVault(newPass,{name:'Cofre recuperado del prototipo'});for(const {o,files} of decoded.reverse()){const r=await addMemory(fresh.vault,fresh.key,{title:o.title,note:o.note,date:o.date?.slice(0,10),symbolicOpening:o.when,ownerConsent:true,peopleConsent:true,channel:'legacy_import'},files);fresh.vault=r.vault}return fresh}
export class VaultStore{
 constructor(name='legad-family-v3'){this.name=name;this.connection=null}
 async db(){if(this.connection)return this.connection;return this.connection=await new Promise((resolve,reject)=>{const r=indexedDB.open(this.name,1);r.onupgradeneeded=()=>{r.result.createObjectStore('vaults');r.result.createObjectStore('settings')};r.onerror=()=>reject(r.error);r.onsuccess=()=>{r.result.onversionchange=()=>{r.result.close();this.connection=null};resolve(r.result)}})}
 async active(){const db=await this.db();return new Promise((resolve,reject)=>{const t=db.transaction(['settings','vaults']),r=t.objectStore('settings').get('active');let value=null;r.onsuccess=()=>{if(r.result){const q=t.objectStore('vaults').get(r.result);q.onsuccess=()=>value=q.result}};t.oncomplete=()=>resolve(value);t.onabort=()=>reject(t.error)})}
 async save(v,expected=null){validateEnvelope(v);const expectedJSON=expected===null?null:JSON.stringify(expected);const db=await this.db();return new Promise((resolve,reject)=>{const t=db.transaction(['vaults','settings'],'readwrite'),s=t.objectStore('vaults'),r=s.get(v.id);let conflict=false;r.onsuccess=()=>{if(expected===null?r.result:!r.result||JSON.stringify(r.result)!==expectedJSON){conflict=true;t.abort();return}s.put(v,v.id);t.objectStore('settings').put(v.id,'active')};t.oncomplete=()=>resolve();t.onabort=()=>reject(new Error(conflict?'El cofre cambió en otra pestaña. Ciérralo y vuelve a abrirlo.':t.error?.message||'No se pudo guardar; conserva una copia externa'))})}
 async restore(v){validateEnvelope(v);const db=await this.db();return new Promise((resolve,reject)=>{const t=db.transaction(['vaults','settings'],'readwrite'),s=t.objectStore('vaults'),q=s.get(v.id);q.onsuccess=()=>{if(q.result){const archived=clone(q.result);s.put(archived,'preserved-'+uuid())}s.put(v,v.id);t.objectStore('settings').put(v.id,'active')};t.oncomplete=()=>resolve();t.onabort=()=>reject(t.error)})}
 async preserved(){const active=await this.active();const db=await this.db();return new Promise((resolve,reject)=>{const t=db.transaction('vaults'),r=t.objectStore('vaults').openCursor(),out=[];r.onsuccess=()=>{const c=r.result;if(!c)return;if(c.key!==active?.id)out.push({storageKey:c.key,vault:c.value});c.continue()};t.oncomplete=()=>resolve(out);t.onabort=()=>reject(t.error)})}
 async remove(id){const db=await this.db();return new Promise((resolve,reject)=>{const t=db.transaction(['vaults','settings'],'readwrite'),s=t.objectStore('vaults'),r=s.openCursor();r.onsuccess=()=>{const c=r.result;if(!c)return;if(c.value?.id===id)c.delete();c.continue()};const q=t.objectStore('settings').get('active');q.onsuccess=()=>{if(q.result===id)t.objectStore('settings').delete('active')};t.oncomplete=()=>resolve();t.onabort=()=>reject(t.error)})}
 close(){this.connection?.close();this.connection=null}
}
